#!/usr/bin/env bash
# GSZ step138 — password-change + propagation. New /account/security page lets a
# logged-in customer change their store password; on change the site emails AND
# WhatsApps them a security confirmation. New routes/accountSecurity.js + view +
# wa_templates row. Patches server.js (mount) + account dashboard (link).
# Idempotent; restores on failure. Robust health check (polls ~25s).
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step138-$TS"; TMP=$(mktemp -d)
PATCHED=(server.js views/account/dashboard.ejs)
NEW=(routes/accountSecurity.js views/account/security.ejs)
echo "==> step138: change password + security notification"
mkdir -p "$BK"; for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore(){
  echo "!! FAILED — restoring"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done
  pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."
}
trap 'restore' ERR
echo "==> writing new files"; mkdir -p "$GSZ/routes" "$GSZ/views/account"
echo "" | base64 -d > "$GSZ/routes/accountSecurity.js"
echo ""  | base64 -d > "$GSZ/views/account/security.ejs"
echo "" | base64 -d > "$TMP/p.js"
echo ""   | base64 -d > "$TMP/m.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/accountSecurity.js"; node --check "$GSZ/server.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/account/security.ejs','views/account/dashboard.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"
echo "==> migrating db"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
echo "==> waiting for app to come up"
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] && echo "    homepage 200: OK (after ${i}s)" || { echo "    homepage $CODE after ${i}s"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step138 OK ✅  Customers can change their password at Account → 'Change password' (/account/security). Each change emails + WhatsApps them a security confirmation."
